function generarRangoFechas(fechaInicio, fechaFin) {
  const d0 = new Date(fechaInicio + 'T00:00:00Z');
  const d1 = new Date(fechaFin + 'T00:00:00Z');
  if (d1 < d0) {
    throw new Error('RANGO_INVALIDO: fecha_fin (' + fechaFin + ') es anterior a fecha_inicio (' + fechaInicio + ').');
  }
  if (d0.getUTCFullYear() !== d1.getUTCFullYear() || d0.getUTCMonth() !== d1.getUTCMonth()) {
    throw new Error('RANGO_CRUZA_MES: fecha_inicio y fecha_fin deben pertenecer al mismo mes (misma regla que run_batch.generar_rango_fechas en V2).');
  }
  const fechas = [];
  let actual = new Date(d0);
  while (actual <= d1) {
    fechas.push(actual.toISOString().slice(0, 10));
    actual.setUTCDate(actual.getUTCDate() + 1);
  }
  return fechas;
}

function nombreCierreEsperado(fechaIso) {
  const partes = fechaIso.split('-');
  const anio = partes[0], mes = partes[1], dia = partes[2];
  return 'CIERRE ' + dia + '-' + mes + '-' + anio + '.xlsm';
}

// Puerto directo de run_batch.generar_rango_fechas()/nombre_cierre_esperado()
// (V2, sin cambios) — ver v3/ingesta.py que SI reutiliza esas funciones por
// import en Python; aqui en n8n (JS) se replica la misma regla porque un
// Code node no puede importar codigo Python.
const params = $('ENTRADA (Execute Workflow Trigger)').first().json;
const fechas = generarRangoFechas(params.fecha_inicio, params.fecha_fin);

return fechas.map((fecha) => ({
  json: { fecha: fecha, archivo_esperado: nombreCierreEsperado(fecha) },
}));

// Puerto JS de v3/ingesta.buscar_cierre_exacto() (Python, verificado en
// parity_v3/test_parity_scenarios.py::test_PARITY_010). Mantener ambos en
// sincronia manualmente si se edita cualquiera de los dos lados.
const ENCONTRADO = 'ENCONTRADO';
const SIN_ARCHIVO = 'SIN_ARCHIVO';
const AMBIGUO = 'AMBIGUO';

const MENSAJES = {
  ENCONTRADO: 'Archivo localizado por coincidencia exacta de nombre.',
  SIN_ARCHIVO: 'Ninguna coincidencia exacta de nombre en la carpeta de entrada.',
  AMBIGUO: 'Mas de una coincidencia exacta de nombre: requiere decision humana, nunca se toma la primera.',
};

function buscarCierreExacto(nombreBuscado, candidatos) {
  const normalizados = (candidatos || []).map((c) => (typeof c === 'string' ? { nombre: c, file_id: null } : c));
  const exactos = normalizados.filter((c) => c.nombre === nombreBuscado);
  if (exactos.length === 1) return [ENCONTRADO, exactos[0].file_id || null, 1];
  if (exactos.length === 0) return [SIN_ARCHIVO, null, 0];
  return [AMBIGUO, null, exactos.length];
}

// DEV: candidatos_por_fecha llega DIRECTO del trigger (fixture explicito).
// EN PRODUCCION futura, este valor deberia venir de un paso previo de
// listado de Drive de SOLO LECTURA (aun no conectado — ver Sticky Note de
// este subworkflow y auditoria_v2/V2_RISKS.csv). Este nodo nunca escribe,
// mueve ni borra nada en Drive.
const candidatosPorFecha = $('ENTRADA (Execute Workflow Trigger)').first().json.candidatos_por_fecha || {};

return $input.all().map((item) => {
  const fecha = item.json.fecha;
  const archivoEsperado = item.json.archivo_esperado;
  let estado, driveFileId, coincidencias, mensaje;
  try {
    const candidatos = candidatosPorFecha[fecha] || [];
    const r = buscarCierreExacto(archivoEsperado, candidatos);
    estado = r[0]; driveFileId = r[1]; coincidencias = r[2];
    mensaje = MENSAJES[estado];
  } catch (e) {
    estado = 'ERROR_INGESTA';
    driveFileId = null;
    coincidencias = null;
    mensaje = e.message;
  }
  return {
    json: {
      fecha: fecha,
      archivo_esperado: archivoEsperado,
      estado_ingesta: estado,
      drive_file_id: driveFileId,
      coincidencias: coincidencias,
      mensaje: mensaje,
    },
  };
});
